        private static List<PlanPoint> P(params double[] coordinates) {
            var points = new List<PlanPoint>(coordinates.Length / 2);
            for (int index = 0; index + 1 < coordinates.Length; index += 2) points.Add(new PlanPoint(coordinates[index], coordinates[index + 1]));
            return points;
        }

        private static List<IReadOnlyList<PlanPoint>> Polygons(params List<PlanPoint>[] polygons) {
            return new List<IReadOnlyList<PlanPoint>>(polygons);
        }

